fn solve(lines: Vec<Vec<char>>) -> Vec<char> {
    // We know `lines` is 3×3, so we can index directly:
    vec![
        lines[0][0],  // top-left
        lines[1][1],  // center
        lines[2][2],  // bottom-right
        '\n',         // newline as the fourth element
    ]
}

